<?php
require __DIR__ . '/functions.php';
$lang = current_lang();
$locations = require __DIR__ . '/locations.php';
$quickAction = $_GET['action'] ?? '';
if ($quickAction === 'add' || $quickAction === 'minus') { $id = (int)($_GET['id'] ?? 0); set_cart_quantity($id, (int)($_SESSION['cart'][$id] ?? 0) + ($quickAction === 'add' ? 1 : -1)); header('Location: index.php?view=cart'); exit; }
if ($_SERVER['REQUEST_METHOD'] === 'POST') { check_csrf(); $id = (int)($_POST['product_id'] ?? 0); if (($_POST['action'] ?? '') === 'add') add_to_cart($id, (int)($_POST['quantity'] ?? 1)); if (($_POST['action'] ?? '') === 'remove') remove_from_cart($id); header('Location: index.php?view=cart'); exit; }
$view = $_GET['view'] ?? 'shop'; $category = $_GET['category'] ?? ''; $query = $_GET['q'] ?? '';
$statement = db()->prepare('SELECT * FROM products WHERE active = 1 AND (? = "" OR category = ?) AND (name LIKE ? OR description LIKE ?) ORDER BY id DESC'); $like = "%$query%"; $statement->execute([$category, $category, $like, $like]); $products = $statement->fetchAll(); $lines = cart_products(); $subtotal = array_reduce($lines, fn($sum, $line) => $sum + ($line['price'] * $line['quantity']), 0); $shipping = $lines ? 700 : 0;
?><!doctype html><html lang="<?= $lang ?>" dir="<?= $lang === 'ar' ? 'rtl' : 'ltr' ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lissi | <?= text('shop') ?></title><link rel="stylesheet" href="style.css"></head><body><header class="header shell"><a class="brand" href="index.php"><img src="assets/logo.jpeg" alt="Lissi"><span>LISSI</span></a><nav class="nav"><a href="index.php"><?= text('shop') ?></a><a href="?category=Women&lang=<?= $lang ?>"><?= text('women') ?></a><a href="?category=Men&lang=<?= $lang ?>"><?= text('men') ?></a><a href="?category=Accessories&lang=<?= $lang ?>"><?= text('accessories') ?></a></nav><div class="header-tools"><a class="bag" href="?view=cart&lang=<?= $lang ?>"><?= text('bag') ?> (<?= cart_count() ?>)</a><a href="?lang=ar">ع</a><a href="?lang=fr">FR</a><a href="?lang=en">EN</a><button class="theme-toggle" type="button" data-theme-toggle aria-label="Toggle theme">◐</button></div></header>
<?php if ($view === 'cart'): ?><section class="section shell"><p class="eyebrow"><?= text('bag') ?></p><h2><?= text('bag') ?></h2><?php if (!$lines): ?><p><?= $lang === 'ar' ? 'السلة فارغة حالياً.' : 'Your bag is waiting for something good.' ?> <a href="index.php?lang=<?= $lang ?>"><?= text('shop') ?></a></p><?php else: ?><?php foreach ($lines as $line): ?><div class="line"><div class="art" style="background:<?= e($line['image_color']) ?>"><strong><?= e($line['short_name']) ?></strong></div><div><b><?= e($line['name']) ?></b><span><?= money($line['price']) ?></span><div class="step"><a aria-label="Decrease quantity" href="?view=cart&action=minus&id=<?= $line['id'] ?>">−</a><span><?= $line['quantity'] ?></span><a aria-label="Increase quantity" href="?view=cart&action=add&id=<?= $line['id'] ?>">+</a><form method="post"><input type="hidden" name="csrf" value="<?= csrf() ?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="product_id" value="<?= $line['id'] ?>"><button type="submit">×</button></form></div></div></div><?php endforeach; ?><div class="summary"><div><span><?= $lang === 'ar' ? 'المجموع الفرعي' : 'Subtotal' ?></span><b><?= money($subtotal) ?></b></div><div><span><?= $lang === 'ar' ? 'التوصيل' : 'Delivery' ?></span><b><?= money($shipping) ?></b></div><div class="total"><span>Total</span><b><?= money($subtotal + $shipping) ?></b></div><a class="dark" href="checkout.php?lang=<?= $lang ?>"><?= text('checkout') ?> · COD →</a></div><?php endif; ?></section>
<?php else: ?><section class="hero shell"><div class="hero-copy"><p class="eyebrow">The everyday edit / 01</p><h1><?= $lang === 'ar' ? 'اختيارات جميلة<br><em>ليومك العادي</em>' : 'Good things,<br><em>beautifully</em> chosen.' ?></h1><p><?= $lang === 'ar' ? 'قطع مختارة بعناية، سهلة الحب ومصممة لتدوم.' : 'Thoughtful pieces for the way you live now. Easy to love, made to last.' ?></p><a class="dark" href="#catalog"><?= text('find') ?> ↓</a></div><div class="hero-art"></div></section><section id="catalog" class="section shell"><div class="section-head"><div><p class="eyebrow"><?= $lang === 'ar' ? 'وصل حديثاً' : 'Just in' ?></p><h2><?= text('find') ?></h2></div><div class="filters"><a class="<?= !$category ? 'active' : '' ?>" href="?lang=<?= $lang ?>"><?= text('all') ?></a><a class="<?= $category === 'Women' ? 'active' : '' ?>" href="?category=Women&lang=<?= $lang ?>"><?= text('women') ?></a><a class="<?= $category === 'Men' ? 'active' : '' ?>" href="?category=Men&lang=<?= $lang ?>"><?= text('men') ?></a><a class="<?= $category === 'Accessories' ? 'active' : '' ?>" href="?category=Accessories&lang=<?= $lang ?>"><?= text('accessories') ?></a></div></div><div class="grid"><?php foreach ($products as $product): ?><article class="card"><form method="post"><div class="art" style="background:<?= e($product['image_color']) ?>"><strong><?= e($product['short_name']) ?></strong><small><?= e($product['color']) ?></small></div><div class="meta"><div><b><?= e($product['name']) ?></b><span><?= e($product['category']) ?> · <?= e($product['sizes']) ?></span></div><b><?= money($product['price']) ?></b></div><div class="stock <?= $product['stock'] < 5 ? 'low' : '' ?>"><i></i><?= $product['stock'] < 5 ? ($lang === 'ar' ? 'بقي ' . $product['stock'] : 'Only ' . $product['stock'] . ' left') : ($lang === 'ar' ? 'متوفر' : 'In stock') ?></div><input type="hidden" name="csrf" value="<?= csrf() ?>"><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?= $product['id'] ?>"><button class="dark" type="submit"><?= text('add') ?> +</button></form></article><?php endforeach; ?></div></section><?php endif; ?><footer class="footer shell"><div><b>LISSI</b><p><?= $lang === 'ar' ? 'أشياء صغيرة، مختارة بعناية.' : 'Little things, thoughtfully chosen.' ?></p></div><div><b>hello@lissi.dz</b><p>Sat–Thu, 9am–6pm</p></div></footer><script>const locations=<?= json_encode($locations, JSON_UNESCAPED_UNICODE) ?>;const toggle=document.querySelector('[data-theme-toggle]');const saved=localStorage.getItem('lissi-theme');if(saved)document.documentElement.dataset.theme=saved;toggle?.addEventListener('click',()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem('lissi-theme',next)});</script></body></html>
